INSERT INTO `commodity` VALUES (51, 2, '帕特冻干猫粮1.8kg成猫生骨肉粮', 219.00, '1.8kg', 7300, 300, '/api/images/goods/mock_good.jpg', '生骨肉冻干，还原猫咪天然食性', '<p>帕特冻干猫粮添加生骨肉颗粒，高蛋白高营养，符合猫咪原始猎食习惯，美毛护肤，提升免疫力。</p>', 1, '深圳', 0.00);
