INSERT INTO `commodity` VALUES (53, 2, '法米娜石榴鸡猫粮5kg成猫进口粮', 569.00, '5kg', 4100, 150, '/api/images/goods/mock_good.jpg', '进口高端粮，美毛护肾强体质', '<p>法米娜进口猫粮采用石榴鸡肉配方，美毛护肤，保护猫咪肾脏，营养密度高，适口性极佳。</p>', 1, '武汉', 6.00);
