INSERT INTO `commodity` VALUES (55, 2, '百利无谷鸡肉猫粮4.5磅进口猫粮', 239.00, '2kg', 5800, 220, '/api/images/goods/mock_good.jpg', '无谷低敏，保护猫咪肠胃健康', '<p>百利无谷猫粮不含谷物，适合肠胃敏感猫咪，高蛋白营养，促进肌肉发育，提升猫咪活力。</p>', 1, '河北', 6.00);
INSERT INTO `commodity` VALUES (56, 2, '有鱼冻干猫粮6kg成猫双拼粮', 299.00, '6kg', 9200, 400, '/api/images/goods/mock_good.jpg', '冻干双拼，营养美味双重享受', '<p>有鱼双拼猫粮添加多种冻干肉类，提升适口性，富含动物蛋白，美毛增肌，猫咪爱吃不挑食。</p>', 1, '山东', 0.00);
