INSERT INTO `commodity` VALUES (89, 6, '猫咪赖氨酸膏120g预防猫鼻支营养膏', 65.00, '120g/支', 15400, 750, '/api/images/goods/mock_good.jpg', '赖氨酸膏，预防猫鼻支增强免疫', '<p>猫咪赖氨酸膏补充赖氨酸，抑制猫鼻支病毒，增强免疫力，改善打喷嚏、流鼻涕症状。</p>', 1, '北京', 0.00);
INSERT INTO `commodity` VALUES (90, 6, '狗狗关节宝软骨素300片老年犬健骨', 79.00, '300片/瓶', 9600, 450, '/api/images/goods/mock_good.jpg', '关节软骨素，保护老年犬关节', '<p>狗狗关节宝添加葡萄糖胺与软骨素，修复关节软骨，缓解关节疼痛，适合老年犬与大型犬。</p>', 1, '广州', 6.00);
INSERT INTO `commodity` VALUES (91, 6, '宠物美毛卵磷脂300g狗狗爆毛粉', 59.00, '300g/罐', 21300, 1000, '/api/images/goods/mock_good.jpg', '美毛卵磷脂，爆毛亮毛防掉毛', '<p>宠物卵磷脂富含不饱和脂肪酸，滋养毛囊，减少掉毛，让狗狗毛发浓密亮丽，爆毛效果明显。</p>', 1, '深圳', 0.00);
INSERT INTO `commodity` VALUES (92, 6, '猫咪牛磺酸片200片明目护心保健品', 39.00, '200片/瓶', 16700, 800, '/api/images/goods/mock_good.jpg', '牛磺酸片，明目护心保护视力', '<p>猫咪牛磺酸片补充必需牛磺酸，保护猫咪心脏与视力健康，适合各年龄段猫咪日常保健。</p>', 1, '成都', 0.00);
INSERT INTO `commodity` VALUES (93, 6, '宠物体内外驱虫药狗狗猫咪通用滴剂', 89.00, '1支/盒', 12100, 550, '/api/images/goods/mock_good.jpg', '驱虫滴剂，体内外同驱更方便', '<p>宠物驱虫滴剂可驱杀体内外寄生虫，操作简单，安全温和，狗狗猫咪通用，保护宠物健康。</p>', 1, '武汉', 6.00);
INSERT INTO `commodity` VALUES (94, 6, '狗狗消食片150片调理肠胃促消化', 29.00, '150片/瓶', 23400, 1100, '/api/images/goods/mock_good.jpg', '消食片，调理肠胃促消化吸收', '<p>狗狗消食片帮助消化食物，缓解积食、腹胀、消化不良，增强食欲，调理肠胃健康。</p>', 1, '杭州', 0.00);
INSERT INTO `commodity` VALUES (95, 6, '宠物液体钙猫咪狗狗快速补钙口服液', 55.00, '100ml/瓶', 11200, 500, '/api/images/goods/mock_good.jpg', '液体钙，吸收快补钙更高效', '<p>宠物液体钙易吸收，快速补充钙质，促进骨骼发育，适合幼犬、幼猫与产后宠物补钙。</p>', 1, '河北', 6.00);
INSERT INTO `commodity` VALUES (96, 6, '猫咪复合维生素片200片全维补充', 42.00, '200片/瓶', 17800, 850, '/api/images/goods/mock_good.jpg', '复合维生素，全面补充猫咪营养', '<p>猫咪复合维生素含多种维生素矿物质，改善挑食、掉毛、体弱问题，增强免疫力。</p>', 1, '山东', 0.00);
INSERT INTO `commodity` VALUES (97, 6, '宠物口腔清洁喷剂狗狗猫咪除口臭', 35.00, '50ml/瓶', 19500, 950, '/api/images/goods/mock_good.jpg', '口腔喷剂，清新口气去除口臭', '<p>宠物口腔喷剂温和无刺激，直接喷洒口腔，抑菌消炎，快速去除口臭，保护口腔健康。</p>', 1, '广东', 0.00);
INSERT INTO `commodity` VALUES (98, 1, '皇家GR26金毛专用成犬粮12kg', 459.00, '12kg', 6700, 300, '/api/images/goods/mock_good.jpg', '金毛专用粮，强健骨骼护关节', '<p>皇家金毛专用粮根据金毛生理特点设计，高蛋白高钙，保护关节健康，促进肌肉发育，体态健壮。</p>', 1, '上海', 0.00);
INSERT INTO `commodity` VALUES (99, 1, '安贝幼犬助长狗粮2kg离乳期专用', 69.00, '2kg', 14300, 700, '/api/images/goods/mock_good.jpg', '幼犬助长配方，生长发育更快', '<p>安贝幼犬粮添加生长因子与钙质，助力离乳期幼犬快速发育，增强体质，易消化吸收。</p>', 1, '北京', 6.00);
INSERT INTO `commodity` VALUES (100, 1, '豪爵天然狗粮5kg成犬低盐美毛粮', 159.00, '5kg', 12500, 600, '/api/images/goods/mock_good.jpg', '低盐配方，美毛护色亮毛发', '<p>豪爵天然粮低盐低油，添加深海鱼油，美毛护色，适合毛发干枯、掉毛严重的狗狗。</p>', 1, '广州', 0.00);
INSERT INTO `commodity` VALUES (101, 1, '新比尤特幼犬粮10kg牛肉味狗粮', 169.00, '10kg', 19800, 950, '/api/images/goods/mock_good.jpg', '牛肉味幼犬粮，营养均衡长身体', '<p>新比尤特幼犬粮牛肉味口感好，营养全面，促进幼犬骨骼发育，适合中大型犬幼犬。</p>', 1, '深圳', 0.00);
INSERT INTO `commodity` VALUES (102, 2, '皇家i27室内成猫粮10kg去毛球专用', 399.00, '10kg', 8900, 400, '/api/images/goods/mock_good.jpg', '室内猫去毛球，护肠胃促排毛', '<p>皇家i27猫粮添加膳食纤维，帮助猫咪排出毛球，减少毛球堆积，保护肠胃健康。</p>', 1, '成都', 6.00);
INSERT INTO `commodity` VALUES (103, 2, '凯锐思无谷幼猫粮1.5kg深海鱼味', 59.00, '1.5kg', 24600, 1200, '/api/images/goods/mock_good.jpg', '深海鱼幼猫粮，增肥发腮好吸收', '<p>凯锐思幼猫粮深海鱼配方，高蛋白低敏，助力幼猫发育，增肥发腮，猫咪爱吃。</p>', 1, '武汉', 0.00);
INSERT INTO `commodity` VALUES (104, 2, '麦富迪佰萃猫粮10kg成猫小鱼干粮', 159.00, '10kg', 32100, 1500, '/api/images/goods/mock_good.jpg', '小鱼干双拼，适口性超强', '<p>麦富迪佰萃猫粮添加小鱼干颗粒，香气浓郁，吸引挑食猫咪，营养均衡，价格亲民。</p>', 1, '杭州', 6.00);
INSERT INTO `commodity` VALUES (105, 3, '狗狗三文鱼零食冻干300g美毛零食', 69.00, '300g', 15400, 750, '/api/images/goods/mock_good.jpg', '三文鱼冻干，美毛护肤营养高', '<p>三文鱼冻干富含Omega3，滋养狗狗毛发，美毛护肤，无添加剂，健康又美味。</p>', 1, '河北', 0.00);
INSERT INTO `commodity` VALUES (106, 3, '宠物鸡肉卷甘薯350g狗狗磨牙零食', 32.00, '350g', 21300, 1000, '/api/images/goods/mock_good.jpg', '鸡肉卷甘薯，磨牙洁齿促消化', '<p>鸡肉卷甘薯口感丰富，磨牙洁齿，甘薯促进肠道蠕动，帮助消化，狗狗超爱吃。</p>', 1, '山东', 0.00);
INSERT INTO `commodity` VALUES (107, 3, '猫咪虾仁冻干100g高蛋白低脂零食', 45.00, '100g', 9600, 450, '/api/images/goods/mock_good.jpg', '虾仁冻干，鲜香美味高蛋白', '<p>虾仁冻干采用新鲜虾仁制作，低脂高蛋白，鲜香美味，猫咪爱吃不发胖，营养健康。</p>', 1, '广东', 0.00);
INSERT INTO `commodity` VALUES (108, 4, '宠物漏食球玩具狗狗解闷智力玩具', 29.00, '1件', 17800, 850, '/api/images/goods/mock_good.jpg', '漏食球，消磨时间锻炼智力', '<p>漏食球可装入零食，狗狗啃咬滚动出粮，消磨时间，锻炼智力，缓解分离焦虑。</p>', 1, '上海', 0.00);
INSERT INTO `commodity` VALUES (109, 4, '猫咪弹簧老鼠玩具自嗨逗猫玩具5个装', 12.00, '5个/包', 32500, 1800, '/api/images/goods/mock_good.jpg', '弹簧老鼠，猫咪自嗨玩耍神器', '<p>弹簧老鼠玩具弹性十足，猫咪拍打追逐，独自玩耍也开心，消耗精力不拆家。</p>', 1, '北京', 0.00);
INSERT INTO `commodity` VALUES (110, 5, '宠物冰垫夏季降温凉垫狗狗猫咪睡垫', 29.00, '1件', 27800, 1400, '/api/images/goods/mock_good.jpg', '夏季冰垫，降温解暑凉爽舒适', '<p>宠物冰垫夏季降温神器，凝胶材质凉爽舒适，防水易清洗，猫狗睡觉解暑专用。</p>', 1, '广州', 6.00);
INSERT INTO `commodity` VALUES (111, 5, '狗狗洗澡刷猫咪沐浴按摩刷硅胶刷', 12.00, '1件', 26700, 1300, '/api/images/goods/mock_good.jpg', '硅胶按摩刷，洗澡按摩更舒服', '<p>硅胶洗澡刷柔软不伤皮肤，洗澡时按摩肌肤，清洁毛发深层污垢，猫狗通用。</p>', 1, '深圳', 0.00);
INSERT INTO `commodity` VALUES (112, 6, '宠物益生菌粉5g*30袋狗狗调理肠胃', 49.00, '30袋/盒', 22100, 1100, '/api/images/goods/mock_good.jpg', '高活性益生菌，调理肠胃止腹泻', '<p>高活性益生菌粉调节肠道菌群，改善腹泻、便秘、消化不良，适合应激反应与肠胃脆弱宠物。</p>', 1, '成都', 0.00);
INSERT INTO `commodity` VALUES (113, 6, '狗狗美毛粉200g泰迪金毛亮毛增色', 55.00, '200g/罐', 14300, 700, '/api/images/goods/mock_good.jpg', '美毛增色粉，泰迪金毛专用亮毛', '<p>狗狗美毛粉针对泰迪、金毛设计，提亮毛色，减少褪色，让毛发柔顺亮丽有光泽。</p>', 1, '武汉', 6.00);
INSERT INTO `commodity` VALUES (114, 1, '欧恩焙鸡鸭肉狗粮4.5kg低温烘焙粮', 389.00, '4.5kg', 5200, 200, '/api/images/goods/mock_good.jpg', '低温烘焙粮，保留营养更健康', '<p>欧恩焙低温烘焙狗粮保留原料营养，低油低盐，易消化，保护狗狗肠胃与心血管健康。</p>', 1, '杭州', 0.00);
INSERT INTO `commodity` VALUES (115, 1, '皇家PR27泰迪专用成犬粮2kg', 99.00, '2kg', 16700, 800, '/api/images/goods/mock_good.jpg', '泰迪专用粮，美毛增色去泪痕', '<p>皇家泰迪专用粮针对泰迪毛发与泪痕特点设计，亮毛祛泪痕，颗粒小巧易咀嚼。</p>', 1, '河北', 6.00);
INSERT INTO `commodity` VALUES (116, 2, '希尔斯泌尿道处方猫粮1.8kg猫咪护肾', 229.00, '1.8kg', 4300, 150, '/api/images/goods/mock_good.jpg', '泌尿道处方粮，保护猫咪泌尿健康', '<p>希尔斯处方粮调节猫咪尿液PH值，预防泌尿道疾病，保护肾脏，适合术后与体弱猫咪。</p>', 1, '山东', 0.00);
INSERT INTO `commodity` VALUES (117, 2, '发育宝猫粮2kg成猫天然粮低敏', 89.00, '2kg', 18900, 900, '/api/images/goods/mock_good.jpg', '天然低敏粮，温和护肠胃', '<p>发育宝成猫粮天然低敏配方，温和不刺激，添加益生元，调理肠胃，营养均衡好吸收。</p>', 1, '广东', 0.00);
INSERT INTO `commodity` VALUES (118, 3, '狗狗鳕鱼粒400g美毛护肤零食', 35.00, '400g', 19800, 950, '/api/images/goods/mock_good.jpg', '鳕鱼粒低脂，美毛护肤不发胖', '<p>鳕鱼粒低脂高蛋白，富含鱼油，美毛护肤，适合需要控制体重的狗狗食用。</p>', 1, '上海', 0.00);
INSERT INTO `commodity` VALUES (119, 3, '猫咪鸡小胸冻干300g增肥发腮零食', 69.00, '300g', 23400, 1100, '/api/images/goods/mock_good.jpg', '鸡小胸冻干，纯肉增肥发腮', '<p>鸡小胸冻干纯肉无添加，高蛋白高热量，帮助猫咪快速增肥发腮，体态圆润。</p>', 1, '北京', 0.00);
